//! The event stream as a JSON Schema document, written from the constants in this module (`e6.7`,
//! [`reco-raw`]).
//!
//! ADR-002 §4.3: *a generated schema is generated by the crate or type that owns the model, and then blessed
//! and diff-tested*. The stream is owned here, so the document is built here. It is assembled from the same
//! [`SCHEMA_VERSION`], [`CONTRACT`], [`Kind`] names and field list the serialiser uses, and
//! `crates/fathom-core/tests/events.rs` refuses a checked-in file that differs from what this returns — which
//! is the half that makes "generated" mean something rather than "written twice".
//!
//! Two properties the payload schemas do not need and this one does:
//!
//! * **A line is written now and read much later.** A stream written by `0.4` is read by `0.6`; a reader from
//!   `0.4` reads a `0.6` file too. So an unknown *field* is skipped, an unknown *kind* survives as an
//!   undeclared kind, and only an unreadable *version* stops a line. The document says all three, because a
//!   consumer reading only the schema should not have to guess.
//! * **The file is `.jsonl`, not a document.** This schema describes **one line**. A short last line is a
//!   crash rather than a format, and [`super::read_stream`] reports it and keeps going.
//!
//! [`reco-raw`]: ../../../.plan/plan.json

use serde_json::{Value, json};

use super::{CONTRACT, MAX_SUBSCRIBERS, SCHEMA_VERSION, kind::ALL};

/// Where the generated document lives, relative to the repository root — the same directory as every other
/// published schema, because it is the same kind of promise.
pub const SCHEMA_FILE: &str = "schemas/fathom-analysis-events.schema.json";

/// The `$id`, in the form every schema here uses.
pub const SCHEMA_ID: &str = "https://fathom.dev/schemas/fathom-analysis-events.schema.json";

/// The contract id, spelled the way the payload contracts spell theirs: name, slash, version.
pub const CONTRACT_ID: &str = "fathom-analysis-events/1";

/// The plan key that owns this contract.
pub const OWNER: &str = "e6.7";

/// The comment that heads the generated file, naming how to regenerate it. A file nobody knows how to
/// regenerate is a file that gets hand-edited the first time it annoys somebody.
const GENERATOR_COMMENT: &str = "Generated by `fathom_core::events::schema::to_text()`, blessed by \
                                 `FATHOM_BLESS=1 cargo test -p fathom-core --test events`. Do not \
                                 hand-edit: change the types or this generator and bless again. \
                                 Owner: `e6.7` (`reco-raw`).";

/// The schema for **one line** of the stream.
#[must_use]
pub fn document() -> Value {
    let kinds: Vec<&str> = ALL.to_vec();
    json!({
        "$comment": GENERATOR_COMMENT,
        "$id": SCHEMA_ID,
        "title": "fathom analysis event — one line of the stream",
        "description": "One thing that happened in one fathom run, as one JSON object on one line of a \
                        `.jsonl` file. Written by `fathom why`/`fathom analyze` when the stream is switched \
                        on, read back by `fathom events`. A file is a sequence of these lines and nothing \
                        else; a line whose `schema_version` this reader cannot read is skipped by name, a \
                        field it has not heard of is skipped, and a kind it has not heard of survives as an \
                        undeclared kind, because the file outlives the build that wrote it.",
        "type": "object",
        "required": ["contract", "schema_version", "kind", "seq", "run"],
        "properties": {
            "contract": {
                "const": CONTRACT,
                "description": "Which stream this line belongs to. A line whose contract is not this is not \
                                a malformed event; it is the wrong file.",
                "type": "string"
            },
            "schema_version": {
                "enum": [SCHEMA_VERSION],
                "description": "The version of this shape the writer wrote. Additive changes keep it; a \
                                reader that cannot read the number says so by name and moves on (which is \
                                the whole benefit of the number).",
                "type": "integer"
            },
            "kind": {
                "description": "What happened, spelled `family.fact` — `run`, `analysis`, `detector`, \
                                `finding`, `notice`, `gate`, `export`, `watch`. The list below is what this \
                                build declares; a kind outside it is an undeclared kind, kept and printed, \
                                never a failure.",
                "type": "string",
                "enum": kinds,
                "pattern": "^[a-z][a-z0-9_]*\\.[a-z][a-z0-9_]*$"
            },
            "seq": {
                "description": "This event's position in its run, stamped by the bus and never by the \
                                producer, so a stream can be read in order even when two writers share it.",
                "minimum": 0,
                "type": "integer"
            },
            "run": {
                "description": "One id per verb invocation, e.g. `why-1792855784071`. Two runs writing one \
                                stream are pulled apart by this and not by a clock they may not agree on.",
                "type": "string"
            },
            "ts": {
                "description": "Wall-clock microseconds since the epoch, supplied by the caller — the domain \
                                crate has no clock (ADR-002 §4.1). A reader must not assume it is present.",
                "type": "integer"
            },
            "episode": {
                "description": "The episode the event is about, when there is one.",
                "type": "string"
            },
            "detector": {
                "description": "The detector or plugin finding type the event is about. For a plugin's \
                                finding this is the namespaced `plugin.type`, which is what makes a \
                                plugin's findings routable.",
                "type": "string"
            },
            "outcome": {
                "description": "What the thing did: `ran`, `disabled`, `not_examined`, `suppressed`, `ok`, \
                                `error`. `disabled` and `not_examined` are outcomes with the same shape as \
                                `ran` so \"did it look?\" has one answer.",
                "type": "string"
            },
            "subject": {
                "description": "The subject inside the episode — a path, a symbol, a queue id.",
                "type": "string"
            },
            "severity": {
                "description": "As the finding model spells it: `high`, `medium`, `low`.",
                "enum": ["high", "medium", "low"],
                "type": "string"
            },
            "counts": {
                "additionalProperties": true,
                "description": "The numbers, named (`findings`, `hidden`, `suppressed`, `code`, `files`, \
                                `added`, `deleted`, `gaps`, …). Names are stable within a major and a name a \
                                reader has not seen is a number to ignore; this is where a new measurement \
                                arrives without breaking anybody.",
                "propertyNames": {"pattern": "^[a-z][a-z0-9_]*$"},
                "type": "object",
                "additionalProperties": {"type": "integer"}
            },
            "note": {
                "description": "The sentence: a notice, a refusal's reason, a finding's message. Free text, \
                                and redacted by the writer before the line leaves the process — the schema \
                                is not the privacy boundary and does not claim to be.",
                "type": "string"
            },
            "producer": {
                "description": "What wrote the line, version included, so a stream that spans an upgrade \
                                says so in the stream.",
                "type": "string"
            },
            "repository": {
                "description": "The repository as a label — a name, never an absolute path.",
                "type": "string"
            }
        },
        "x-fathom": {
            "capability": "fathom why|analyze --events, read back by `fathom events`",
            "contract": CONTRACT_ID,
            "owner": OWNER,
            "version": SCHEMA_VERSION,
            "this_build_reads": [SCHEMA_VERSION],
            "compatibility": "additive within a version; an unreadable version is a line a reader skips by \
                              name, which is what lets a newer build write for an older reader",
            "reader_ignores_unknown_fields": true,
            "unknown_kinds": "an undeclared kind is kept with its name rather than refused, because the file \
                              outlives the build that wrote it",
            "transport": "one object per line (`.jsonl`); this schema describes a line, not the file",
            "cap": {
                "subscribers": MAX_SUBSCRIBERS,
                "note": "a producer refuses more than this many subscribers and counts the refusal rather \
                        than slowing every publish down to grow a list"
            },
            "consumer": [
                "fathom-cli (`fathom events`)",
                "a repository's own log shipper",
                "the out-of-tree example plugin's contract test"
            ]
        }
    })
}

/// The document in the bytes the blessed file holds: two-space indentation and a trailing newline, so a
/// regenerated diff is the diff of the contract and not of the formatter.
#[must_use]
pub fn to_text() -> String {
    let mut text = serde_json::to_string_pretty(&document()).unwrap_or_else(|_| String::from("{}"));
    text.push('\n');
    text
}
